{"content": "// goldbach.c — verify strong Goldbach for all even n in [4, 1e6]
// Method: sieve of Eratosthenes (odds-only bitset), then for each even n
// scan p = 3,5,7,... up to n/2 and test primality of n-p via sieve.
// Compile: gcc -O2 -o goldbach goldbach.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define LIMIT 1000000

static uint8_t *is_comp; // is_comp[i]=1 => i composite; index by odd number m -> (m>>1)

static inline int is_prime(uint32_t m) {
    if (m < 2) return 0;
    if (m == 2) return 1;
    if (!(m & 1)) return 0;
    return !is_comp[m >> 1];
}

int main(void) {
    // sieve odds up to LIMIT: is_comp bit for odd m>=3 at index m>>1
    size_t sz = (LIMIT >> 1) + 1;
    is_comp = calloc(sz, 1);
    if (!is_comp) { fprintf(stderr, "alloc fail\n"); return 1; }
    for (uint32_t i = 3; (uint64_t)i * i <= LIMIT; i += 2) {
        if (!is_comp[i >> 1]) {
            for (uint64_t j = (uint64_t)i * i; j <= LIMIT; j += 2u * i)
                is_comp[j >> 1] = 1;
        }
    }

    FILE *f = fopen("artifacts/goldbach_witnesses.txt", "w");
    if (!f) { fprintf(stderr, "open witnesses fail\n"); return 1; }

    uint64_t checked = 0;
    uint32_t max_primes_needed = 0;
    clock_t t0 = clock();
    for (uint32_t n = 4; n <= LIMIT; n += 2) {
        int found = 0;
        if (is_prime(n - 2)) { // p=2 case
            fprintf(f, "%u 2 %u\n", n, n - 2);
            found = 1;
            checked++;
            continue;
        }
        for (uint32_t p = 3; p <= n / 2; p += 2) {
            if (is_prime(p) && is_prime(n - p)) {
                fprintf(f, "%u %u %u\n", n, p, n - p);
                found = 1;
                break;
            }
        }
        if (!found) {
            printf("COUNTEREXAMPLE: %u\n", n);
            fclose(f);
            return 2;
        }
        checked++;
    }
    clock_t t1 = clock();
    double secs = (double)(t1 - t0) / CLOCKS_PER_SEC;
    printf("OK: verified all %llu even n in [4, %d]\n", (unsigned long long)checked, LIMIT);
    printf("time: %.3f s\n", secs);
    fclose(f);
    return 0;
}
", "path": "goldbach.c"}

{"content": "# goldbach.awk — strong Goldbach verifier for all even n in [4, N], N=1,000,000
# Algorithm: sieve of Eratosthenes (odds only) + ascending-prime scan for first
# representation n = p + q, p <= q. Emits one witness line "n p q" per even n.
# Usage: awk -v N=1000000 -v WIT=artifacts/goldbach_witnesses.txt -f goldbach.awk
BEGIN {
  if (N == "") N = 1000000
  if (WIT == "") WIT = "artifacts/goldbach_witnesses.txt"
  # --- sieve: C[int(m/2)]=1  <=>  odd m (3<=m<=N) is composite ---
  for (i = 3; i * i <= N; i += 2) {
    if (!C[int(i / 2)]) {
      for (j = i * i; j <= N; j += 2 * i) C[int(j / 2)] = 1
    }
  }
  # --- dense prime list of ALL primes <= N (for pi(N) self-check + scan) ---
  np = 1; P[1] = 2
  for (m = 3; m <= N; m += 2) if (!C[int(m / 2)]) P[++np] = m
  piN = np
  # pi(N/2): primes available as summand p <= n/2
  piHalf = 0
  for (k = 1; k <= np && P[k] <= int(N / 2); k++) piHalf++
  largest = P[np]
  # --- main scan ---
  cnt = 0
  for (n = 4; n <= N; n += 2) {
    if (n == 4) { print "4 2 2" > WIT; cnt++; continue }
    half = int(n / 2)
    found = 0
    for (k = 2; k <= np; k++) {        # k=1 is p=2; n-2 even>2 => composite, skip
      p = P[k]
      if (p > half) break
      if (!C[int((n - p) / 2)]) { print n, p, n - p > WIT; found = 1; break }
    }
    if (!found) { printf "COUNTEREXAMPLE %d\n", n > "/dev/stderr"; bad++; exit 2 }
    cnt++
  }
  close(WIT)
  printf "RESULT OK even_n_checked=%d range=[4,%d] pi(%d)=%d pi(%d)=%d largest_prime<=%d\n", cnt, N, N, piN, int(N / 2), piHalf, largest
}
", "path": "goldbach.awk"}

{"content": "# goldbach_audit.awk — independent cross-check, different algorithm & data path.
# Differences vs goldbach.awk:
#   * full boolean sieve (not odds-only), trial-division-free
#   * DESCENDING scan from the largest prime <= n/2 (opposite direction)
#   * reads the witness file from run 1 and RE-VERIFIES each witness line
#     (n even, p<=q, p+q=n, p and q prime) using its own sieve
#   * recomputes the count of even n and compares to witness-line count
# Usage: awk -v N=1000000 -v WIT=artifacts/goldbach_witnesses.txt -f goldbach_audit.awk
BEGIN {
  if (N == "") N = 1000000
  # --- full sieve: S[m]=1 <=> m prime, 0<=m<=N ---
  for (m = 2; m <= N; m++) S[m] = 1
  for (m = 2; m * m <= N; m++) if (S[m]) for (j = m * m; j <= N; j += m) S[j] = 0
  # --- re-verify every witness line from run 1 ---
  wlines = 0; wbad = 0
  while ((getline line < WIT) > 0) {
    wlines++
    split(line, a, " ")
    n = a[1] + 0; p = a[2] + 0; q = a[3] + 0
    if (n % 2 != 0 || n < 4 || n > N) { wbad++; if (wbad <= 5) print "BADLINE", line }
    else if (p + q != n) { wbad++; if (wbad <= 5) print "BADSUM", line }
    else if (p > q) { wbad++; if (wbad <= 5) print "BADORDER", line }
    else if (!S[p] || !S[q]) { wbad++; if (wbad <= 5) print "BADPRIME", line }
  }
  close(WIT)
  # --- independent descending re-scan of all even n ---
  miss = 0; cnt = 0
  for (n = 4; n <= N; n += 2) {
    cnt++
    found = 0
    for (p = int(n / 2); p >= 2; p--) {
      if (S[p] && S[n - p]) { found = 1; break }
    }
    if (!found) { print "AUDIT-COUNTEREXAMPLE", n; miss++ }
  }
  printf "AUDIT RESULT witness_lines=%d witness_bad=%d even_n=%d misses=%d\n", wlines, wbad, cnt, miss
  if (wlines != cnt) printf "AUDIT MISMATCH witness_lines(%d) != even_n(%d)\n", wlines, cnt
  if (wbad == 0 && miss == 0 && wlines == cnt) print "AUDIT VERDICT: PASS"
  else print "AUDIT VERDICT: FAIL"
}
", "path": "goldbach_audit.awk"}

